import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    S = input_data[0]
    K = int(input_data[1])

    n = len(S)
    if K > n:
        print(0)
        return

    freq = [0] * 26
    distinct_count = 0
    count = 0

    def get_index(char):
        return ord(char) - ord('a')

    for i in range(K):
        idx = get_index(S[i])
        if freq[idx] == 0:
            distinct_count += 1
        freq[idx] += 1

    if distinct_count == K - 1:
        count += 1

    for i in range(K, n):
        out_char_idx = get_index(S[i - K])
        in_char_idx = get_index(S[i])

        freq[out_char_idx] -= 1
        if freq[out_char_idx] == 0:
            distinct_count -= 1

        if freq[in_char_idx] == 0:
            distinct_count += 1
        freq[in_char_idx] += 1

        if distinct_count == K - 1:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
